custom_css:
/*
=========================================
   一、 变量定义 (雪落)
========================================= 
*/
:root {
    --white-bg-paper: rgba(250, 250, 250, 1);       
    --white-bg-panel: rgba(255, 255, 255, 0.85);    
    --white-dark: rgba(70, 70, 70, 0.9);              
    --white-light: rgba(160, 160, 160, 1);          
    --white-pale: rgba(255, 255, 255, 0.9);         
    --white-line-color: rgba(220, 220, 220, 0.5);   

    --white-text-input: "落雪无痕 提笔留念...";
    --white-text-load: "—— 翻阅前尘 ——";
    --white-text-cot: "【踏雪寻痕】";
    --white-text-signature: "“白水鉴心 我心可鉴”";

    --white-icon-size-top: 15px;         
    --white-bubble-width: 98%;           
    --white-bubble-max-width: 1200px;    
}

/* 
=========================================
   二、 全局排版与字体 
========================================= 
*/
body {
    background-color: var(--white-bg-paper) !important;
    color: var(--white-dark) !important;
    font-family: var(--bamboo-font-main) !important;
    letter-spacing: 0.05em; 
}

h2, h3, h4, .standoutHeader strong {
    font-family: var(--bamboo-font-title) !important;
    color: var(--white-dark) !important;
    font-weight: normal !important;
    border: none !important;
    background: transparent !important;
    text-shadow: none !important;
}

body * {
    box-shadow: none !important;
    filter: none !important;
}

* { 
    scrollbar-width: none !important; 
}
::-webkit-scrollbar { 
    display: none !important; 
    width: 0 !important; 
    height: 0 !important; 
}
::-webkit-scrollbar-track { background: transparent !important; }
::-webkit-scrollbar-thumb { background: transparent !important; }

/* 
=========================================
   三、 顶栏与底栏 
========================================= 
*/
#top-bar, #top-settings-holder {
    background-color: var(--white-bg-panel) !important;
    border-bottom: 1px solid var(--white-line-color) !important;
    box-shadow: none !important;
    backdrop-filter: blur(8px);
}

#top-settings-holder .drawer-icon {
    font-size: var(--white-icon-size-top) !important; 
    color: var(--white-dark) !important;
    opacity: 0.55 !important; 
    transition: all 0.3s ease !important; 
}

#top-settings-holder .drawer-toggle:hover .drawer-icon,
#top-settings-holder .drawer-icon:not(.closedIcon) {
    opacity: 1 !important;
    transform: scale(1.05) !important; 
}

#form_sheld { 
    margin: 0 !important; 
    background-color: var(--paper) !important; 
    border: none !important; 
    box-shadow: none !important;
}
#form_sheld > div:first-child { background: transparent !important; border: none !important; }
#chat_bottom, #form_sheld hr { display: none !important; }

#form_sheld::before, #form_sheld::after,
#send_form::before, #send_form::after {
    display: none !important;
    content: none !important;
}

#send_form {
    display: flex !important;
    align-items: center !important;
    width: 100% !important;
    min-height: 30px !important;
    margin: 0 auto !important;
    padding: 2px 10px !important;
    background: var(--paper) !important; 
    border: none !important; 
    border-radius: 0 !important; 
    box-shadow: none !important;
}

#nonQRFormItems {
    flex: 1 1 auto !important;
    display: flex !important;
    align-items: center !important;
    padding: 0 6px !important;
    background: transparent !important;
    border: none !important;
    position: relative;
}

#nonQRFormItems textarea, #send_textarea {
    flex: 1 1 auto !important;
    background: transparent !important;
    border: none !important;
    outline: none !important;
    color: var(--ink) !important;
    font-size: 10px !important;
    line-height: 20px !important;
    min-height: 20px !important;
    padding: 4px 0 !important;
}

#send_textarea::placeholder {
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--white-text-input);
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    font-family: var(--bamboo-font-title);
    font-size: 12px;
    color: var(--white-light);
    pointer-events: none;
    letter-spacing: 2px;
}

#leftSendForm > div, #rightSendForm > div {
    transform: scale(0.5) translateY(-4px) !important;
    color: var(--ink-3) !important;
    opacity: 0.6 !important;
    transition: color 0.25s ease, opacity 0.25s ease !important;
}
#send_form:focus-within #leftSendForm > div,
#send_form:focus-within #rightSendForm > div { opacity: 0.8 !important; }
#leftSendForm > div:hover, #rightSendForm > div:hover {
    opacity: 1 !important;
    color: var(--ink) !important;
}

#show_more_messages {
    background: transparent !important;
    border: none !important;
    border-top: 1px solid var(--line) !important;
    border-bottom: 1px solid var(--line) !important;
    font-size: 0 !important;
    padding: 10px 0 !important;
    margin: 20px auto !important;
    display: block !important;
    box-shadow: none !important;
}
#show_more_messages::before {
    content: var(--white-text-load);
    font-size: 14px !important;
    font-family: var(--bamboo-font-title);
    color: var(--white-light);
    letter-spacing: 4px;
    transition: color 0.3s;
}
#show_more_messages:hover::before { 
    color: var(--white-dark); 
}

/* 
=========================================
   四、 聊天界面与气泡 
========================================= 
*/
#chat {
    background-color: transparent !important;
    padding: 15px !important;
}

.mes {
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 10px 0 !important;
    margin-top: 25px !important; 
    margin-bottom: 20px !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    overflow: visible !important; 
    position: relative !important;
}

.mes:has(.swipes-counter:not(:empty)) .mes_block {
    padding-bottom: 35px !important;
}

.mes .mes_block {
    background-color: var(--white-pale) !important;
    backdrop-filter: blur(2px) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 12px !important; 
    padding: 20px 25px !important;
    margin: 5px auto !important; 
    width: var(--white-bubble-width) !important;
    max-width: var(--white-bubble-max-width) !important;
    box-shadow: none !important;
}

div[is_user="true"] .mes_block {
    background-color: rgba(255, 255, 255, 0.6) !important;
}

.mes .mes_text {
    color: var(--white-dark) !important;
    line-height: 2 !important; 
    text-align: justify !important; 
    margin: 0 auto !important; 
    padding: 0 !important;     
    width: 100% !important;    
}

/* 
=========================================
   五、 头像、名字与三元素区域
========================================= 
*/
.mes .mesAvatarWrapper {
    display: grid !important;
    grid-template-columns: auto auto auto !important;
    justify-content: center !important;
    justify-items: center !important;
    align-items: center !important;
    column-gap: 18px !important;
    row-gap: 6px !important;
    width: 100% !important;
    margin: 0 auto 12px auto !important;
    padding: 0 !important;
    position: relative !important;
    z-index: 10 !important;
}

.mes .mesAvatarWrapper .avatar {
    grid-column: 1 / -1 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
    margin: 0 auto !important;
    padding: 0 !important;
    width: 55px !important;
    height: 55px !important;
    min-height: 55px !important;
    overflow: visible !important;
}

.mes .avatar img {
    width: 55px !important;
    height: 55px !important;
    border-radius: 16px !important;
    border: 1px solid var(--white-light) !important;
    padding: 2px !important;
    background-color: #fff !important;
    display: block !important;
    object-fit: cover !important; 
    box-sizing: border-box !important;
}

.mes .mesAvatarWrapper::after {
    content: var(--white-text-signature) !important;
    grid-column: 1 / -1 !important;
    grid-row: 2 !important; 
    display: block !important;
    width: 100% !important;
    text-align: center !important;
    font-size: 13px !important;
    font-family: var(--bamboo-font-title) !important;
    color: var(--white-light) !important;
    margin: 4px auto !important; 
    letter-spacing: 2px !important;
    text-indent: 2px !important;
    white-space: nowrap !important;
    line-height: 1.5 !important;
}

.mes .mesAvatarWrapper .avatar::after {
    display: none !important;
}

.mes .mesAvatarWrapper .mesIDDisplay {
    grid-column: 1 !important;
    grid-row: 3 !important; 
}
.mes .mesAvatarWrapper .mes_timer {
    grid-column: 2 !important;
    grid-row: 3 !important; 
}
.mes .mesAvatarWrapper .tokenCounterDisplay {
    grid-column: 3 !important;
    grid-row: 3 !important; 
}

.mes .mesAvatarWrapper .mesIDDisplay,
.mes .mesAvatarWrapper .mes_timer,
.mes .mesAvatarWrapper .tokenCounterDisplay {
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: auto !important;
    min-width: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    font-size: 12px !important;
    line-height: 1.5 !important;
    font-family: var(--bamboo-font-main) !important;
    font-weight: normal !important;
    color: var(--white-dark) !important;
    white-space: nowrap !important;
}

.mes .mesAvatarWrapper .mesIDDisplay::before {
    content: "第 ";
    font-size: 11px !important;
    color: var(--white-light) !important;
}
.mes .mesAvatarWrapper .mesIDDisplay::after {
    content: " 贴";
    font-size: 11px !important;
    color: var(--white-light) !important;
    margin-left: 2px !important;
}

.mes .mesAvatarWrapper .tokenCounterDisplay::before {
    content: "共 ";
    font-size: 11px !important;
    color: var(--white-light) !important;
    margin-right: 2px !important;
}
.mes .mesAvatarWrapper .tokenCounterDisplay::after {
    content: " 词";
    font-size: 11px !important;
    color: var(--white-light) !important;
    margin-left: 2px !important;
}

.mes .mesAvatarWrapper .mes_timer {
    color: var(--white-light) !important;
}

.mes .mesAvatarWrapper .mesIDDisplay:empty,
.mes .mesAvatarWrapper .mes_timer:empty,
.mes .mesAvatarWrapper .tokenCounterDisplay:empty {
    display: none !important;
}

/* 
=========================================
   六、 特殊文本修饰 (Quotes, Italics, Code)
========================================= 
*/
.mes_text q,
.mes_text blockquote {
    color: var(--white-dark) !important;
    font-family: var(--bamboo-font-title) !important; 
    background-color: rgba(245, 245, 245, 0.6) !important; 
    border: 1px dashed var(--white-light) !important; 
    border-radius: 6px !important; 
    padding: 2px 6px !important; 
    margin: 0 2px !important;
    text-decoration: none !important;
    -webkit-box-decoration-break: clone !important;
    box-decoration-break: clone !important;
    display: inline !important; 
    line-height: 2.2 !important; 
}

.mes_text blockquote p {
    display: inline !important;
    margin: 0 !important;
    padding: 0 !important;
}

.mes_text em {
    font-style: normal !important;
    color: var(--white-dark) !important;
    text-decoration: underline !important;
    text-decoration-style: dotted !important;
    text-decoration-color: var(--white-light) !important;
    text-underline-offset: 4px;
}

pre, code {
    background-color: rgba(255, 255, 255, 0.5) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 4px !important;
    color: var(--white-dark) !important;
    font-family: "Courier New", monospace, var(--bamboo-font-main) !important;
}

/* 
=========================================
   七、 思维链 (CoT)
========================================= 
*/
.mes_reasoning_arrow, .mes_reasoning_summary::-webkit-details-marker { display: none !important; }
.mes_reasoning_header_title { font-size: 0 !important; }
.mes_reasoning_header {
    background: transparent !important;
    border: 1px dashed var(--white-line-color) !important;
    border-radius: 4px !important;
    padding: 4px 10px !important;
}
.mes_reasoning_header_title::before {
    content: var(--white-text-cot) !important;
    font-size: 13px !important;
    font-family: var(--bamboo-font-title);
    color: var(--white-light);
}
.mes_reasoning {
    background: rgba(255,255,255,0.4) !important;
    border: 1px dotted var(--white-line-color) !important;
    border-radius: 4px !important;
    padding: 10px !important;
    font-size: 14px !important;
    color: rgba(70, 70, 70, 0.8) !important;
}

/* 
=========================================
   八、 抽屉面板与控件 
========================================= 
*/
.drawer-content {
    background-color: var(--white-bg-panel) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 8px !important;
    box-shadow: 0 10px 30px rgba(0,0,0,0.05) !important;
}

input[type="text"], input[type="number"], select, textarea {
    background-color: rgba(255,255,255,0.7) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 4px !important;
    color: var(--white-dark) !important;
}

input:focus, textarea:focus, select:focus {
    border-color: var(--white-light) !important;
    outline: none !important;
}

.menu_button, .right_menu_button {
    background-color: transparent !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 4px !important;
    color: var(--white-dark) !important;
}

.menu_button:hover, .right_menu_button:hover {
    background-color: var(--white-pale) !important;
    border-color: var(--white-light) !important;
}

/* 
=========================================
   九、 通知提示条 
========================================= 
*/
#toast-container > div {
    background-color: var(--white-bg-panel) !important;
    backdrop-filter: blur(8px) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 8px !important;
    color: var(--white-dark) !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.05) !important;
    font-family: var(--bamboo-font-main) !important;
    opacity: 1 !important; 
}

#toast-container > .toast-success {
    background-color: rgba(245, 245, 245, 0.6) !important; 
}
#toast-container > .toast-error {
    background-color: rgba(253, 240, 245, 0.6) !important;
    color: #8b4555 !important;
    border-color: rgba(200, 150, 160, 0.4) !important;
}
#toast-container > .toast-warning {
    background-color: rgba(253, 245, 235, 0.6) !important;
    color: #8b6545 !important;
    border-color: rgba(200, 170, 150, 0.4) !important;
}

/* 
=========================================
   十、 预设管理器与扩展面板
========================================= 
*/
#completion_prompt_manager_list {
    background-color: transparent !important;
    border: none !important;
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt {
    background-color: var(--white-bg-panel) !important; 
    border: 1px solid var(--white-line-color) !important; 
    border-radius: 8px !important;
    margin-bottom: 6px !important;
    padding: 8px 12px !important;
    color: var(--white-dark) !important; 
    box-shadow: 0 2px 8px rgba(0,0,0,0.02) !important;
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    background-color: var(--white-pale) !important;
    border-color: var(--white-light) !important;
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt.selected {
    background-color: var(--white-pale) !important;
    border-left: 4px solid var(--white-light) !important;
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt * {
    color: var(--white-dark) !important;
    text-shadow: none !important;
}

#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
    background-color: rgba(245, 245, 245, 0.7) !important; 
    border: 1px dashed var(--white-line-color) !important; 
    opacity: 0.9 !important; 
}
#completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled * {
    color: rgba(120, 120, 120, 0.6) !important; 
    -webkit-text-fill-color: rgba(120, 120, 120, 0.6) !important;
}

.inline-drawer-toggle,
.inline-drawer-header,
.extension_button,
.list-group-item {
    background-image: none !important; 
    background-color: var(--white-bg-panel) !important; 
    color: var(--white-dark) !important; 
    border: 1px solid var(--white-line-color) !important; 
    text-shadow: none !important;         
    border-radius: 8px !important;
    margin-top: 4px !important;
    margin-bottom: 4px !important;
    padding: 8px 12px !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.02) !important;
}

.inline-drawer-content {
    background-color: rgba(255, 255, 255, 0.5) !important; 
    border: 1px solid var(--white-line-color) !important;
    border-radius: 8px !important;
    margin-bottom: 10px !important;
    padding: 10px !important;
    color: var(--white-dark) !important;
}

.extension_container .menu_button {
    background-color: var(--white-bg-panel) !important;
    color: var(--white-dark) !important;
    border: 1px solid var(--white-line-color) !important;
}
.extension_container .menu_button:hover {
    background-color: var(--white-pale) !important;
}

/* 
=========================================
   十一、 API与AI预设面板
========================================= 
*/
input:disabled, input[readonly], 
textarea:disabled, textarea[readonly], 
select:disabled, .disabled_input {
    background-color: rgba(245, 245, 245, 0.6) !important; 
    color: rgba(120, 120, 120, 0.6) !important; 
    border: 1px dashed var(--white-line-color) !important; 
    opacity: 1 !important;
}

.title_restorable, .standoutHeader {
    background-image: none !important;
    background-color: var(--white-bg-panel) !important; 
    color: var(--white-dark) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 8px !important;
    padding: 8px 12px !important;
    margin-top: 5px !important;
    margin-bottom: 5px !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.02) !important;
}

.title_restorable *, .standoutHeader * {
    color: var(--white-dark) !important;
    text-shadow: none !important;
}

input[type="range"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    background: var(--white-line-color) !important; 
    height: 6px !important;
    border-radius: 3px !important;
    margin: 10px 0 !important;
    box-shadow: inset 0 1px 2px rgba(0,0,0,0.05) !important;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 18px !important;
    height: 18px !important;
    background: var(--white-light) !important; 
    border-radius: 50% !important;
    border: 2px solid #ffffff !important; 
    box-shadow: 0 2px 5px rgba(0,0,0,0.2) !important;
    cursor: pointer !important;
}

.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple {
    background-color: rgba(255, 255, 255, 0.7) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 6px !important;
}
.select2-container--default .select2-selection--single .select2-selection__rendered {
    color: var(--white-dark) !important;
}

.api_button {
    background-color: var(--white-bg-panel) !important;
    color: var(--white-dark) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 6px !important;
    padding: 6px 12px !important;
    transition: all 0.2s ease;
}
.api_button:hover {
    background-color: var(--white-pale) !important;
    border-color: var(--white-light) !important;
}

/* 
=========================================
   十二、 世界书
========================================= 
*/
.flex-container:has(#world_editor_select),
.flex-container:has(#world_search_text) {
    display: flex !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    gap: 6px !important;
    font-size: 0 !important; 
    overflow-x: auto !important;
}
.flex-container:has(#world_editor_select) > *,
.flex-container:has(#world_search_text) > * {
    font-size: 13px !important;
}
#world_editor_select {
    flex: 1 1 100px !important;
    height: 28px !important;
}
#world_search_text {
    flex: 1 1 100px !important;
    height: 28px !important;
    background-color: transparent !important; 
    border: 1px solid var(--white-line-color) !important;
    color: var(--white-dark) !important;
}

#world_info + .select2-container .select2-selection--multiple {
    background-color: var(--white-bg-panel) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 8px !important;
}
.select2-container--default .select2-selection--multiple .select2-selection__choice {
    background-color: var(--white-pale) !important;
    border: 1px solid var(--white-light) !important;
    color: var(--white-dark) !important;
    border-radius: 4px !important;
}
.select2-container--default .select2-selection--multiple .select2-selection__choice__remove {
    color: var(--white-dark) !important;
    background: transparent !important;
    border: none !important;
}

.world_entry {
    background-color: var(--white-bg-panel) !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 8px !important;
    padding: 10px !important;
    margin-bottom: 10px !important;
    box-shadow: 0 4px 15px rgba(0,0,0,0.02) !important;
}
.world_entry .world_entry_form,
.world_entry .inline-drawer-content {
    border: none !important;
    background: transparent !important;
    margin: 0 !important;
    padding: 0 !important;
    box-shadow: none !important;
}

.world_entry .inline-drawer-header {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: nowrap !important;
    align-items: center !important;
    gap: 8px !important;
    width: 100% !important;
    margin: 0 0 8px 0 !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
}

.world_entry .drag-handle,
.world_entry .inline-drawer-toggle,
.world_entry .killSwitch {
    position: static !important;
    margin: 0 !important;
    padding: 0 !important;
    height: auto !important;
    width: auto !important;
    display: inline-flex !important;
    align-items: center !important;
}

.world_entry .WIEntryTitleAndStatus { order: 1 !important; flex: 1 1 auto !important; display: flex !important; gap: 6px !important; }
.world_entry .inline-drawer-toggle { order: 2 !important; color: var(--white-dark) !important; font-size: 16px !important;}
.world_entry .drag-handle { order: 3 !important; color: var(--white-dark) !important; font-size: 16px !important;}
.world_entry .killSwitch { order: 4 !important; color: var(--white-light) !important; font-size: 18px !important;}

.world_entry select[name="entryStateSelector"] {
    flex: 0 0 auto !important;
    width: auto !important;
    padding: 0 4px !important;
    background: transparent !important;
    border: none !important;
    appearance: none !important;
    font-size: 16px !important;
}

.world_entry .world_entry_thin_controls {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 8px !important;
    align-items: flex-end !important;
    margin: 0 0 8px 0 !important;
}
.world_entry .world_entry_form_control {
    margin: 0 !important;
}

.world_entry .world_entry_form_control small {
    font-size: 10px !important;
    color: var(--white-light) !important;
    margin-bottom: 2px !important;
    display: block !important;
}

.world_entry .world_entry_form_control:has(select[name="position"]) {
    flex: 1 1 120px !important;
}
.world_entry .world_entry_form_control:has(input[type="number"]) {
    flex: 0 0 60px !important;
}

.world_entry input[type="text"], 
.world_entry input[type="number"], 
.world_entry select:not([name="entryStateSelector"]) {
    background-color: rgba(255, 255, 255, 0.7) !important;
    border: 1px solid var(--white-line-color) !important;
    color: var(--white-dark) !important;
    border-radius: 4px !important;
    padding: 4px 8px !important;
    font-size: 13px !important;
    height: 28px !important;
    box-sizing: border-box !important;
}

.world_entry textarea {
    width: 100% !important;
    background-color: rgba(255, 255, 255, 0.7) !important;
    border: 1px solid var(--white-line-color) !important;
    color: var(--white-dark) !important;
    border-radius: 4px !important;
    padding: 6px !important;
    font-size: 13px !important;
    resize: vertical !important;
    box-sizing: border-box !important;
}

.world_entry textarea:not([name="content"]) {
    min-height: 45px !important;
    height: 45px !important;
}

.world_entry textarea[name="content"],
.world_entry .text_pole[name="content"] {
    min-height: 150px !important;
    height: auto !important;
}

/* 
=========================================
   十三、 消息操作按钮与滑动计数
========================================= 
*/
.mes .swipe_left {
    position: absolute !important;
    left: 6% !important;
    bottom: 25px !important;
    color: var(--white-light) !important;
    z-index: 10 !important;
    padding: 5px !important;
    cursor: pointer !important;
}

.mes .swipeRightBlock {
    position: absolute !important;
    right: 6% !important;
    bottom: 25px !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    color: var(--white-light) !important;
    z-index: 10 !important;
    padding: 5px !important;
}

.mes .swipes-counter {
    margin-left: 8px !important;
    color: var(--white-dark) !important;
    font-family: var(--bamboo-font-main) !important;
    font-size: 13px !important;
}

.mes .mes_buttons .mes_button, 
.mes .extraMesButtons > div {
    transform: scale(0.8) !important; 
    opacity: 0.5 !important; 
    transition: all 0.2s ease !important;
}

.mes .mes_buttons .mes_button:hover, 
.mes .extraMesButtons > div:hover {
    transform: scale(0.9) !important; 
    opacity: 1 !important; 
    color: var(--white-dark) !important;
}

/* 
=========================================
   十四、 底栏弹出菜单
========================================= 
*/
#options, #extensionsMenu {
    width: auto !important; 
    min-width: 0 !important; 
    max-width: 190px !important;
    padding: 4px !important;
    background-color: var(--white-bg-panel) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: 1px solid var(--white-line-color) !important;
    border-radius: 12px !important;
    opacity: 1 !important;
}

#options .options-content, #extensionsMenu .list-group, #extensionsMenu > div { 
    background: transparent !important; 
    border: none !important; 
    box-shadow: none !important; 
}

#options .interactable, #options a, #extensionsMenu .list-group-item, #extensionsMenu .interactable, .extensionsMenuExtensionButton {
    margin: 0 !important;
    padding: 6px 9px !important;
    background-color: transparent !important;
    background-image: none !important;
    border: none !important;
    border-radius: 8px !important;
    color: var(--white-dark) !important;
    font-size: 12.5px !important;
    transition: background-color 0.2s ease !important;
}

#options .interactable:hover, #options a:hover, #extensionsMenu .list-group-item:hover, #extensionsMenu .interactable:hover, .extensionsMenuExtensionButton:hover {
    background-color: var(--white-pale) !important;
}

#options .interactable .fa-solid, #options .interactable i, #extensionsMenu .fa-solid, #extensionsMenu .list-group-item i, .extensionsMenuExtensionButton .fa-solid {
    color: var(--white-light) !important; 
    font-size: 12px !important;
}
